import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str):
    expected_width = 9
    delimiter = ","

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=delimiter,
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = list(reader)

    def is_blank(record):
        return not record or all(value == "" for value in record)

    def looks_like_header(record):
        if len(record) < 2:
            return False
        first = record[0].lstrip("\ufeff").strip()
        second = record[1].strip()
        if not re.match(r"^[A-Za-z][A-Za-z _-]*$", first):
            return False
        if not re.match(r"^[A-Za-z][A-Za-z _-]*$", second):
            return False
        uppercase_fields = 0
        for value in record:
            value = value.strip()
            if value and re.match(r"^[A-Za-z][A-Za-z0-9 _-]*$", value):
                uppercase_fields += 1
        return uppercase_fields >= min(4, len(record))

    def normalize_header(record):
        values = list(record[:expected_width])
        while len(values) < expected_width:
            values.append("")
        if values:
            values[0] = values[0].lstrip("\ufeff")
        return [value.strip() for value in values]

    def normalize_row(record):
        values = list(record)
        if len(values) == expected_width:
            return values
        if len(values) < expected_width:
            return values + [""] * (expected_width - len(values))

        url_index = -1
        for index in range(6, len(values)):
            if re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", values[index].strip()):
                url_index = index
                break

        if url_index >= 7:
            description = delimiter.join(values[6:url_index])
            url = values[url_index]
            comments = delimiter.join(values[url_index + 1:])
            return values[:6] + [description, url, comments]

        return values[:expected_width - 1] + [delimiter.join(values[expected_width - 1:])]

    header_index = -1
    for index, record in enumerate(records):
        if looks_like_header(record):
            header_index = index
            break

    if header_index >= 0:
        columns = normalize_header(records[header_index])
        data_records = records[header_index + 1:]
    else:
        columns = [
            "column_1", "column_2", "column_3", "column_4", "column_5",
            "column_6", "column_7", "column_8", "column_9"
        ]
        data_records = records

    rows = []
    for record in data_records:
        if is_blank(record):
            continue
        rows.append(normalize_row(record))

    return {"columns": columns, "rows": rows}
